select

from corgi_merchandise m
where m.status = 1

    and m.type = #{merchandise.type}


    and m.app_merch_id = #{merchandise.appMerchId}


order by m.order

select

from corgi_order o

    left join corgi_merchandise m on m.merch_code = o.merch_id

where 1=1

    and o.user_id = #{order.userId}


    and o.market_id = #{order.marketId}


    and o.trade_no = #{order.tradeNo}


    and o.order_id = #{order.orderId}


    and o.pay_amount = #{order.payAmount}


    and o.pay_type = #{order.payType}


    and o.pay_type != 'withdraw'


    and o.seller_id = #{order.userId}


    and o.status = #{order.status}


    and m.type = #{order.merchType}


    and o.ctime > #{order.ctime}

order by o.id desc
limit #{start}, #{size}

select
count(1)
from corgi_order

    left join corgi_merchandise m on m.merch_code = o.merch_id

where 1=1

    and o.user_id = #{order.userId}


    and o.trade_no = #{order.tradeNo}


    and o.status = #{order.status}


    and o.pay_type = #{order.payType}


    and m.type = #{order.merchType}

select

from corgi_order o
where trade_no = #{tradeNo}

mapper.update:
update corgi_order
set receipt = #{receipt}
where trade_no = #{tradeNo}

mapper.select:
select trade_no
from corgi_order
where receipt = #{receipt}
  and user_id = #{userId}

select `user_id` userId,
`goods_type` goodsType,
`merch_id` merchId,
`goods_id` goodsId,
price,
currency,
trader_id traderId,
trade_no tradeNo,
`desc`
`status`,
ctime,
uptime
from corgi_user_goods
where goods_type = #{goods.goodsType}

    and goods_id = #{goods.goodsId}


    and trade_no = #{goods.tradeNo}


    and trader_id = #{goods.traderId}


    and goods_type = #{goods.goodsType}


    and `desc` != #{goods.desc}


    and `ctime` > #{goods.ctime}

and status = '1'

    and user_id = #{goods.userId}

order by id desc limit #{goods.start}, #{goods.size}

select sum(pay_amount) from corgi_order
where status = #{order.status}

    and seller_id = #{order.sellerId}


    and pay_type = #{order.payType}


    and user_id = #{order.userId}
